        ["fr"] = """{"s3.chat.greeting1":"Qu’aimeriez-vous découvrir aujourd’hui ?","s3.chat.greeting2":"Vous avez une idée à organiser ? Nous pouvons y réfléchir ensemble.","s3.chat.greeting3":"Besoin de répondre à une question, de comparer des options ou de préparer un projet ?","s3.chat.greeting4":"Par quoi commencer ? Dites-moi ce que vous cherchez à résoudre.","s3.chat.greeting5":"Je peux expliquer un sujet étape par étape ou en résumer l’essentiel.","s3.chat.greeting6":"Vous travaillez sur quelque chose ? Je peux vous aider à le découper en petites étapes.","s3.chat.greeting7":"Vous pouvez apporter une question, un brouillon ou simplement une idée à explorer.","s3.chat.greeting8":"Qu’est-ce qui vous aiderait le plus : une explication, une relecture ou de nouvelles idées ?","s3.chat.confirmDeleteConversationTitle":"Supprimer cette conversation ?","s3.chat.confirmDeleteConversationText":"Elle sera retirée du chat hors ligne et ne pourra pas être récupérée.","s3.chat.confirmDeleteConversationOk":"Supprimer","s3.chat.confirmDeleteModelTitle":"Supprimer ce modèle ?","s3.chat.confirmDeleteModelText":"Le fichier sera supprimé de ce PC. Vous pourrez le télécharger à nouveau plus tard.","s3.chat.confirmDeleteModelOk":"Supprimer le modèle","s3.chat.confirmDeleteAllTitle":"Supprimer toutes les conversations ?","s3.chat.confirmDeleteAllText":"Cette action est irréversible.","s3.chat.confirmDeleteAllOk":"Tout supprimer","s3.chat.confirmClearMessagesTitle":"Effacer les messages ?","s3.chat.confirmClearMessagesText":"La conversation restera dans la liste, mais elle sera vide.","s3.chat.confirmClearMessagesOk":"Effacer","s3.chat.confirmClearAiTitle":"Supprimer les paramètres de l’IA ?","s3.chat.confirmClearAiText":"La clé API et la connexion enregistrées dans cette application seront supprimées.","s3.chat.confirmClearAiOk":"Supprimer","s3.chat.confirmResetLookTitle":"Rétablir l’apparence par défaut ?","s3.chat.confirmResetLookText":"Le thème, l’arrière-plan, l’assombrissement