        ["de"] = """{"s3.chat.greeting1":"Was möchtest du heute herausfinden?","s3.chat.greeting2":"Möchtest du einen Gedanken ordnen? Wir können ihn gemeinsam weiterentwickeln.","s3.chat.greeting3":"Möchtest du eine Frage klären, Optionen vergleichen oder etwas planen?","s3.chat.greeting4":"Womit sollen wir anfangen? Erzähl mir, was du lösen möchtest.","s3.chat.greeting5":"Ich kann ein Thema Schritt für Schritt erklären oder das Wichtigste zusammenfassen.","s3.chat.greeting6":"Du arbeitest an etwas? Ich helfe dir, es in kleinere Schritte aufzuteilen.","s3.chat.greeting7":"Bring eine Frage, einen Entwurf oder einfach eine Idee mit, die du erkunden möchtest.","s3.chat.greeting8":"Was wäre gerade hilfreich: eine Erklärung, ein Gegenlesen oder neue Ideen?","s3.chat.confirmDeleteConversationTitle":"Dieses Gespräch löschen?","s3.chat.confirmDeleteConversationText":"Es wird aus dem Offline-Chat entfernt und kann nicht wiederhergestellt werden.","s3.chat.confirmDeleteConversationOk":"Löschen","s3.chat.confirmDeleteModelTitle":"Dieses Modell löschen?","s3.chat.confirmDeleteModelText":"Die Datei wird von diesem PC entfernt. Du kannst sie später erneut herunterladen.","s3.chat.confirmDeleteModelOk":"Modell löschen","s3.chat.confirmDeleteAllTitle":"Alle Gespräche löschen?","s3.chat.confirmDeleteAllText":"Diese Aktion kann nicht rückgängig gemacht werden.","s3.chat.confirmDeleteAllOk":"Alle löschen","s3.chat.confirmClearMessagesTitle":"Nachrichten löschen?","s3.chat.confirmClearMessagesText":"Das Gespräch bleibt in der Liste, ist danach aber leer.","s3.chat.confirmClearMessagesOk":"Leeren","s3.chat.confirmClearAiTitle":"KI-Einstellungen entfernen?","s3.chat.confirmClearAiText":"Der gespeicherte API-Schlüssel und die Verbindung werden aus dieser App gelöscht.","s3.chat.confirmClearAiOk":"Entfernen","s3.chat.confirmResetLookTitle":"Darstellung zurücksetzen?","s3.chat.confirmResetLookText":"Design, Hintergrund, Abdunklung, Effekte und Animationen werden auf die Standardwerte zurüc