        ["it"] = """{"s3.chat.greeting1":"Che cosa ti piacerebbe scoprire oggi?","s3.chat.greeting2":"Hai un’idea da mettere in ordine? Possiamo svilupparla insieme.","s3.chat.greeting3":"Vuoi chiarire un dubbio, confrontare alcune opzioni o pianificare qualcosa?","s3.chat.greeting4":"Da dove cominciamo? Raccontami cosa stai cercando di risolvere.","s3.chat.greeting5":"Posso spiegarti un argomento passo dopo passo o riassumere i punti essenziali.","s3.chat.greeting6":"Stai lavorando a qualcosa? Posso aiutarti a dividerlo in passaggi più piccoli.","s3.chat.greeting7":"Puoi portare una domanda, una bozza o semplicemente un’idea da esplorare.","s3.chat.greeting8":"Cosa ti sarebbe più utile ora: una spiegazione, una revisione o nuove idee?","s3.chat.confirmDeleteConversationTitle":"Eliminare questa conversazione?","s3.chat.confirmDeleteConversationText":"Verrà rimossa dalla chat offline e non potrà essere recuperata.","s3.chat.confirmDeleteConversationOk":"Elimina","s3.chat.confirmDeleteModelTitle":"Eliminare questo modello?","s3.chat.confirmDeleteModelText":"Il file verrà rimosso da questo PC. Potrai scaricarlo di nuovo più avanti.","s3.chat.confirmDeleteModelOk":"Elimina modello","s3.chat.confirmDeleteAllTitle":"Eliminare tutte le conversazioni?","s3.chat.confirmDeleteAllText":"Questa azione non può essere annullata.","s3.chat.confirmDeleteAllOk":"Elimina tutto","s3.chat.confirmClearMessagesTitle":"Cancellare i messaggi?","s3.chat.confirmClearMessagesText":"La conversazione resterà nell’elenco, ma sarà vuota.","s3.chat.confirmClearMessagesOk":"Cancella","s3.chat.confirmClearAiTitle":"Rimuovere le impostazioni dell’IA?","s3.chat.confirmClearAiText":"La chiave API e la connessione salvate in questa app verranno eliminate.","s3.chat.confirmClearAiOk":"Rimuovi","s3.chat.confirmResetLookTitle":"Ripristinare l’aspetto predefinito?","s3.chat.confirmResetLookText":"Tema, sfondo, oscuramento, effetti e animazioni torneranno ai valori predefiniti.","s3.chat.confirmResetLookOk":