        ["nl"] = """{"s3.chat.greeting1":"Wat zou je vandaag willen uitzoeken?","s3.chat.greeting2":"Wil je een idee op een rijtje zetten? We kunnen het samen uitwerken.","s3.chat.greeting3":"Wil je een vraag beantwoorden, opties vergelijken of iets plannen?","s3.chat.greeting4":"Waar zullen we beginnen? Vertel me wat je probeert op te lossen.","s3.chat.greeting5":"Ik kan een onderwerp stap voor stap uitleggen of de kern samenvatten.","s3.chat.greeting6":"Ben je ergens mee bezig? Ik kan helpen het in kleinere stappen op te delen.","s3.chat.greeting7":"Kom maar met een vraag, een concept of gewoon een idee om te verkennen.","s3.chat.greeting8":"Wat helpt je nu het meest: uitleg, een controle of nieuwe ideeën?","s3.chat.confirmDeleteConversationTitle":"Dit gesprek verwijderen?","s3.chat.confirmDeleteConversationText":"Het wordt uit de offlinechat verwijderd en kan niet worden hersteld.","s3.chat.confirmDeleteConversationOk":"Verwijderen","s3.chat.confirmDeleteModelTitle":"Dit model verwijderen?","s3.chat.confirmDeleteModelText":"Het bestand wordt van deze pc verwijderd. Je kunt het later opnieuw downloaden.","s3.chat.confirmDeleteModelOk":"Model verwijderen","s3.chat.confirmDeleteAllTitle":"Alle gesprekken verwijderen?","s3.chat.confirmDeleteAllText":"Dit kan niet ongedaan worden gemaakt.","s3.chat.confirmDeleteAllOk":"Alles verwijderen","s3.chat.confirmClearMessagesTitle":"De berichten wissen?","s3.chat.confirmClearMessagesText":"Het gesprek blijft in de lijst staan, maar is daarna leeg.","s3.chat.confirmClearMessagesOk":"Wissen","s3.chat.confirmClearAiTitle":"AI-instellingen verwijderen?","s3.chat.confirmClearAiText":"De in deze app opgeslagen API-sleutel en verbinding worden verwijderd.","s3.chat.confirmClearAiOk":"Verwijderen","s3.chat.confirmResetLookTitle":"De standaardweergave herstellen?","s3.chat.confirmResetLookText":"Thema, achtergrond, dimming, effecten en animaties worden teruggezet naar de standaardinstellingen.","s3.chat.confirmResetLookOk":"Herstellen"