        ["pl"] = """{"s3.chat.greeting1":"Czego chcesz się dziś dowiedzieć?","s3.chat.greeting2":"Masz pomysł, który chcesz uporządkować? Możemy wspólnie go rozwinąć.","s3.chat.greeting3":"Chcesz wyjaśnić wątpliwość, porównać opcje albo coś zaplanować?","s3.chat.greeting4":"Od czego zaczynamy? Opowiedz, co próbujesz rozwiązać.","s3.chat.greeting5":"Mogę wyjaśnić temat krok po kroku albo podsumować najważniejsze informacje.","s3.chat.greeting6":"Pracujesz nad czymś? Pomogę podzielić to na mniejsze etapy.","s3.chat.greeting7":"Możesz zadać pytanie, pokazać szkic albo po prostu podzielić się pomysłem do omówienia.","s3.chat.greeting8":"Co najbardziej Ci teraz pomoże: wyjaśnienie, sprawdzenie tekstu czy nowe pomysły?","s3.chat.confirmDeleteConversationTitle":"Usunąć tę rozmowę?","s3.chat.confirmDeleteConversationText":"Zostanie usunięta z czatu offline i nie będzie można jej odzyskać.","s3.chat.confirmDeleteConversationOk":"Usuń","s3.chat.confirmDeleteModelTitle":"Usunąć ten model?","s3.chat.confirmDeleteModelText":"Plik zostanie usunięty z tego komputera. Później możesz pobrać go ponownie.","s3.chat.confirmDeleteModelOk":"Usuń model","s3.chat.confirmDeleteAllTitle":"Usunąć wszystkie rozmowy?","s3.chat.confirmDeleteAllText":"Tej operacji nie można cofnąć.","s3.chat.confirmDeleteAllOk":"Usuń wszystko","s3.chat.confirmClearMessagesTitle":"Wyczyścić wiadomości?","s3.chat.confirmClearMessagesText":"Rozmowa pozostanie na liście, ale będzie pusta.","s3.chat.confirmClearMessagesOk":"Wyczyść","s3.chat.confirmClearAiTitle":"Usunąć ustawienia AI?","s3.chat.confirmClearAiText":"Zapisany klucz API i połączenie zostaną usunięte z tej aplikacji.","s3.chat.confirmClearAiOk":"Usuń","s3.chat.confirmResetLookTitle":"Przywrócić domyślny wygląd?","s3.chat.confirmResetLookText":"Motyw, tło, przyciemnienie, efekty i animacje wrócą do ustawień domyślnych.","s3.chat.confirmResetLookOk":"Przywróć","s3.chat.confirmClearLearningText":"AI przestanie korzystać z polubionych przez Ciebie odpowiedzi jako przykładów."}""",
        ["tr"] = """{"s3.chat.greeting1":"Bugün neyi keşfetmek istersin?","s3.chat.greeting2":"Düzenlemek istediğin bir fikir var mı? Üzerinde birlikte çalışabiliriz.","s3.chat.greeting3":"Bir soruyu yanıtlamak, seçenekleri karşılaştırmak ya da bir plan yapmak ister misin?","s3.chat.greeting4":"Nereden başlayalım? Çözmeye çalıştığın şeyi anlat.","s3.chat.greeting5":"Bir konuyu adım adım açıklayabilir veya önemli noktaları özetleyebilirim.","s3.chat.greeting6":"Bir şey üzerinde mi çalışıyorsun? Onu daha küçük adımlara bölmene yardımcı olabilirim.","s3.chat.greeting7":"Bir soru, taslak ya da keşfetmek istediğin bir fikirle başlayabiliriz.","s3.chat.greeting8":"Şu an hangisi daha faydalı olur: açıklama, gözden geçirme ya da yeni fikirler?","s3.chat.confirmDeleteConversationTitle":"Bu sohbet silinsin mi?","s3.chat.confirmDeleteConversationText":"Çevrimdışı sohbetten kaldırılacak ve geri getirilemeyecek.","s3.chat.confirmDeleteConversationOk":"Sil","s3.chat.confirmDeleteModelTitle":"Bu model silinsin mi?","s3.chat.confirmDeleteModelText":"Dosya bu bilgisayardan kaldırılacak. Daha sonra yeniden indirebilirsin.","s3.chat.confirmDeleteModelOk":"Modeli sil","s3.chat.confirmDeleteAllTitle":"Tüm sohbetler silinsin mi?","s3.chat.confirmDeleteAllText":"Bu işlem geri alınamaz.","s3.chat.confirmDeleteAllOk":"Tümünü sil","s3.chat.confirmClearMessagesTitle":"Mesajlar temizlensin mi?","s3.chat.confirmClearMessagesText":"Sohbet listede kalır ancak içi boş olur.","s3.chat.confirmClearMessagesOk":"Temizle","s3.chat.confirmClearAiTitle":"Yapay zekâ ayarları kaldırılsın mı?","s3.chat.confirmClearAiText":"Bu uygulamada kayıtlı API anahtarı ve bağlantı silinecek.","s3.chat.confirmClearAiOk":"Kaldır","s3.chat.confirmResetLookTitle":"Görünüm varsayılan ayarlara dönsün mü?","s3.chat.confirmResetLookText":"Tema, arka plan, karartma, efektler ve animasyonlar varsayılan ayarlara dönecek.","s3.chat.confirmResetLookOk":"Sıfırla","s3.chat.confirmClearLearningText":"Yapay zekâ, beğendiğin yanıtları artık örnek olarak kullanmayacak."}""",
        ["ru"] = """{"s3.chat.greeting1":"Что вам хотелось бы узнать сегодня?","s3.chat.greeting2":"Есть идея, которую хочется упорядочить? Давайте вместе её проработаем.","s3.chat.greeting3":"Хотите разобраться с вопросом, сравнить варианты или что-нибудь спланировать?","s3.chat.greeting4":"С чего начнём? Расскажите, что вы пытаетесь решить.","s3.chat.greeting5":"Могу объяснить тему по шагам или кратко изложить главное.","s3.chat.greeting6":"Работаете над чем-то? Помогу разбить задачу на небольшие шаги.","s3.chat.greeting7":"Можно начать с вопроса, черновика или просто идеи для обсуждения.","s3.chat.greeting8":"Что сейчас полезнее: объяснение, проверка текста или новые идеи?","s3.chat.confirmDeleteConversationTitle":"Удалить этот разговор?","s3.chat.confirmDeleteConversationText":"Он будет удалён из офлайн-чата без возможности восстановления.","s3.chat.confirmDeleteConversationOk":"Удалить","s3.chat.confirmDeleteModelTitle":"Удалить эту модель?","s3.chat.confirmDeleteModelText":"Файл будет удалён с этого компьютера. Позже его можно скачать снова.","s3.chat.confirmDeleteModelOk":"Удалить модель","s3.chat.confirmDeleteAllTitle":"Удалить все разговоры?","s3.chat.confirmDeleteAllText":"Это действие нельзя отменить.","s3.chat.confirmDeleteAllOk":"Удалить всё","s3.chat.confirmClearMessagesTitle":"Очистить сообщения?","s3.chat.confirmClearMessagesText":"Разговор останется в списке, но станет пустым.","s3.chat.confirmClearMessagesOk":"Очистить","s3.chat.confirmClearAiTitle":"Удалить настройки ИИ?","s3.chat.confirmClearAiText":"Сохранённый API-ключ и подключение будут удалены из приложения.","s3.chat.confirmClearAiOk":"Удалить","s3.chat.confirmResetLookTitle":"Восстановить исходный вид?","s3.chat.confirmResetLookText":"Тема, фон, затемнение, эффекты и анимация будут возвращены к настройкам по умолчанию.","s3.chat.confirmResetLookOk":"Восстановить","s3.chat.confirmClearLearningText":"ИИ больше не будет использовать понравившиеся вам ответы как примеры."}""",
        ["uk"] = """{"s3.chat.greeting1":"Що вам хотілося б дізнатися сьогодні?","s3.chat.greeting2":"Є ідея, яку хочеться впорядкувати? Можемо разом її опрацювати.","s3.chat.greeting3":"Хочете розібратися з питанням, порівняти варіанти чи щось спланувати?","s3.chat.greeting4":"З чого почнемо? Розкажіть, що ви намагаєтеся вирішити.","s3.chat.greeting5":"Можу пояснити тему крок за кроком або стисло викласти головне.","s3.chat.greeting6":"Працюєте над чимось? Допоможу поділити завдання на менші кроки.","s3.chat.greeting7":"Можна почати із запитання, чернетки або просто ідеї для обговорення.","s3.chat.greeting8":"Що зараз корисніше: пояснення, перевірка тексту чи нові ідеї?","s3.chat.confirmDeleteConversationTitle":"Видалити цю розмову?","s3.chat.confirmDeleteConversationText":"Її буде видалено з офлайн-чату без можливості відновлення.","s3.chat.confirmDeleteConversationOk":"Видалити","s3.chat.confirmDeleteModelTitle":"Видалити цю модель?","s3.chat.confirmDeleteModelText":"Файл буде видалено з цього комп’ютера. Пізніше його можна буде завантажити знову.","s3.chat.confirmDeleteModelOk":"Видалити модель","s3.chat.confirmDeleteAllTitle":"Видалити всі розмови?","s3.chat.confirmDeleteAllText":"Цю дію не можна скасувати.","s3.chat.confirmDeleteAllOk":"Видалити все","s3.chat.confirmClearMessagesTitle":"Очистити повідомлення?","s3.chat.confirmClearMessagesText":"Розмова залишиться у списку, але буде порожньою.","s3.chat.confirmClearMessagesOk":"Очистити","s3.chat.confirmClearAiTitle":"Видалити налаштування ШІ?","s3.chat.confirmClearAiText":"Збережений ключ API та підключення буде видалено з цієї програми.","s3.chat.confirmClearAiOk":"Видалити","s3.chat.confirmResetLookTitle":"Відновити типовий вигляд?","s3.chat.confirmResetLookText":"Тему, тло, затемнення, ефекти й анімацію буде повернуто до типових налаштувань.","s3.chat.confirmResetLookOk":"Відновити","s3.chat.confirmClearLearningText":"ШІ більше не використовуватиме відповіді, які вам сподобалися, як приклади."}""",
        ["ar"] = """{"s3.chat.greeting1":"ما الذي تود اكتشافه اليوم؟","s3.chat.greeting2":"هل لديك فكرة تريد تنظيمها؟ يمكننا تطويرها معًا.","s3.chat.greeting3":"هل تريد الإجابة عن سؤال أو مقارنة خيارات أو التخطيط لشيء ما؟","s3.chat.greeting4":"من أين نبدأ؟ أخبرني بما تحاول حله.","s3.chat.greeting5":"يمكنني شرح موضوع خطوة بخطوة أو تلخيص أهم النقاط.","s3.chat.greeting6":"هل تعمل على شيء؟ يمكنني مساعدتك في تقسيمه إلى خطوات أصغر.","s3.chat.greeting7":"ابدأ بسؤال أو مسودة أو فكرة ترغب في استكشافها.","s3.chat.greeting8":"ما الذي سيساعدك الآن أكثر: شرح أم مراجعة أم أفكار جديدة؟","s3.chat.confirmDeleteConversationTitle":"هل تريد حذف هذه المحادثة؟","s3.chat.confirmDeleteConversationText":"ستُحذف من الدردشة دون اتصال ولن يمكن استعادتها.","s3.chat.confirmDeleteConversationOk":"حذف","s3.chat.confirmDeleteModelTitle":"هل تريد حذف هذا النموذج؟","s3.chat.confirmDeleteModelText":"ستُحذف الملفات من هذا الكمبيوتر، ويمكنك تنزيلها مجددًا لاحقًا.","s3.chat.confirmDeleteModelOk":"حذف النموذج","s3.chat.confirmDeleteAllTitle":"هل تريد حذف جميع المحادثات؟","s3.chat.confirmDeleteAllText":"لا يمكن التراجع عن هذا الإجراء.","s3.chat.confirmDeleteAllOk":"حذف الكل","s3.chat.confirmClearMessagesTitle":"هل تريد مسح الرسائل؟","s3.chat.confirmClearMessagesText":"ستبقى المحادثة في القائمة، لكن ستصبح فارغة.","s3.chat.confirmClearMessagesOk":"مسح","s3.chat.confirmClearAiTitle":"هل تريد إزالة إعدادات الذكاء الاصطناعي؟","s3.chat.confirmClearAiText":"سيُحذف مفتاح API والاتصال المحفوظان في هذا التطبيق.","s3.chat.confirmClearAiOk":"إزالة","s3.chat.confirmResetLookTitle":"هل تريد استعادة المظهر الافتراضي؟","s3.chat.confirmResetLookText":"سيعود المظهر والخلفية والتعتيم والتأثيرات والحركات إلى الإعدادات الافتراضية.","s3.chat.confirmResetLookOk":"استعادة","s3.chat.confirmClearLearningText":"لن يعود الذكاء الاصطناعي يستخدم الردود التي أعجبتك كأمثلة."}""",
        ["ja"] = """{"s3.chat.greeting1":"今日は何を知りたいですか？","s3.chat.greeting2":"考えを整理してみませんか。一緒に形にしていきましょう。","s3.chat.greeting3":"疑問の解決、選択肢の比較、計画づくりなどをお手伝いできます。","s3.chat.greeting4":"何から始めましょう？解決したいことを教えてください。","s3.chat.greeting5":"テーマを順を追って説明したり、要点をまとめたりできます。","s3.chat.greeting6":"取り組んでいることはありますか？小さな手順に分けるお手伝いができます。","s3.chat.greeting7":"質問や下書き、考えてみたいアイデアから始めてみましょう。","s3.chat.greeting8":"今ほしいのは、説明・文章の確認・新しいアイデアのどれですか？","s3.chat.confirmDeleteConversationTitle":"この会話を削除しますか？","s3.chat.confirmDeleteConversationText":"オフラインチャットから削除され、元に戻せません。","s3.chat.confirmDeleteConversationOk":"削除","s3.chat.confirmDeleteModelTitle":"このモデルを削除しますか？","s3.chat.confirmDeleteModelText":"ファイルはこのPCから削除されます。後で再ダウンロードできます。","s3.chat.confirmDeleteModelOk":"モデルを削除","s3.chat.confirmDeleteAllTitle":"すべての会話を削除しますか？","s3.chat.confirmDeleteAllText":"この操作は取り消せません。","s3.chat.confirmDeleteAllOk":"すべて削除","s3.chat.confirmClearMessagesTitle":"メッセージを消去しますか？","s3.chat.confirmClearMessagesText":"会話は一覧に残りますが、メッセージは空になります。","s3.chat.confirmClearMessagesOk":"消去","s3.chat.confirmClearAiTitle":"AIの設定を削除しますか？","s3.chat.confirmClearAiText":"このアプリに保存されたAPIキーと接続設定が削除されます。","s3.chat.confirmClearAiOk":"削除","s3.chat.confirmResetLookTitle":"外観を初期設定に戻しますか？","s3.chat.confirmResetLookText":"テーマ、背景、暗さ、エフェクト、アニメーションが初期設定に戻ります。","s3.chat.confirmResetLookOk":"戻す","s3.chat.confirmClearLearningText":"「いいね」した回答は、AIの応答例として使われなくなります。"}""",
        ["ko"] = """{"s3.chat.greeting1":"오늘은 무엇을 알아보고 싶으신가요?","s3.chat.greeting2":"정리하고 싶은 아이디어가 있나요? 함께 구체화해 볼 수 있어요.","s3.chat.greeting3":"궁금한 점을 풀거나, 선택지를 비교하거나, 계획을 세워 볼까요?","s3.chat.greeting4":"무엇부터 시작할까요? 해결하려는 일을 알려 주세요.","s3.chat.greeting5":"주제를 차근차근 설명하거나 핵심만 요약해 드릴 수 있어요.","s3.chat.greeting6":"진행 중인 일이 있나요? 작은 단계로 나누는 걸 도와드릴게요.","s3.chat.greeting7":"질문이나 초안, 함께 살펴보고 싶은 아이디어를 가져와 보세요.","s3.chat.greeting8":"지금 필요한 건 설명, 검토, 새로운 아이디어 중 무엇인가요?","s3.chat.confirmDeleteConversationTitle":"이 대화를 삭제할까요?","s3.chat.confirmDeleteConversationText":"오프라인 채팅에서 삭제되며 복구할 수 없습니다.","s3.chat.confirmDeleteConversationOk":"삭제","s3.chat.confirmDeleteModelTitle":"이 모델을 삭제할까요?","s3.chat.confirmDeleteModelText":"파일이 이 PC에서 삭제됩니다. 나중에 다시 다운로드할 수 있습니다.","s3.chat.confirmDeleteModelOk":"모델 삭제","s3.chat.confirmDeleteAllTitle":"모든 대화를 삭제할까요?","s3.chat.confirmDeleteAllText":"이 작업은 되돌릴 수 없습니다.","s3.chat.confirmDeleteAllOk":"모두 삭제","s3.chat.confirmClearMessagesTitle":"메시지를 지울까요?","s3.chat.confirmClearMessagesText":"대화는 목록에 남지만 메시지는 모두 비워집니다.","s3.chat.confirmClearMessagesOk":"지우기","s3.chat.confirmClearAiTitle":"AI 설정을 삭제할까요?","s3.chat.confirmClearAiText":"이 앱에 저장된 API 키와 연결 정보가 삭제됩니다.","s3.chat.confirmClearAiOk":"삭제","s3.chat.confirmResetLookTitle":"모양을 기본값으로 되돌릴까요?","s3.chat.confirmResetLookText":"테마, 배경, 어둡기, 효과, 애니메이션이 기본 설정으로 돌아갑니다.","s3.chat.confirmResetLookOk":"복원","s3.chat.confirmClearLearningText":"좋아요한 답변은 더 이상 AI의 응답 예시로 사용되지 않습니다."}""",
        ["zh-CN"] = """{"s3.chat.greeting1":"今天想了解些什么？","s3.chat.greeting2":"有想整理的想法吗？我们可以一起梳理清楚。","s3.chat.greeting3":"想解答问题、比较选项，还是规划一件事？","s3.chat.greeting4":"我们从哪里开始？说说你想解决什么。","s3.chat.greeting5":"我可以逐步讲解一个主题，也可以概括重点。","s3.chat.greeting6":"正在处理什么事情吗？我可以帮你拆分成更小的步骤。","s3.chat.greeting7":"可以从一个问题、一份草稿，或一个想继续探索的想法开始。","s3.chat.greeting8":"现在更需要哪种帮助：解释、检查内容，还是提供新思路？","s3.chat.confirmDeleteConversationTitle":"要删除此对话吗？","s3.chat.confirmDeleteConversationText":"此对话将从离线聊天中删除，且无法恢复。","s3.chat.confirmDeleteConversationOk":"删除","s3.chat.confirmDeleteModelTitle":"要删除此模型吗？","s3.chat.confirmDeleteModelText":"该文件将从此电脑中删除，以后仍可重新下载。","s3.chat.confirmDeleteModelOk":"删除模型","s3.chat.confirmDeleteAllTitle":"要删除所有对话吗？","s3.chat.confirmDeleteAllText":"此操作无法撤销。","s3.chat.confirmDeleteAllOk":"全部删除","s3.chat.confirmClearMessagesTitle":"要清空消息吗？","s3.chat.confirmClearMessagesText":"对话仍会保留在列表中，但内容将被清空。","s3.chat.confirmClearMessagesOk":"清空","s3.chat.confirmClearAiTitle":"要删除 AI 设置吗？","s3.chat.confirmClearAiText":"此应用中保存的 API 密钥和连接信息将被删除。","s3.chat.confirmClearAiOk":"删除","s3.chat.confirmResetLookTitle":"要恢复默认外观吗？","s3.chat.confirmResetLookText":"主题、背景、暗度、特效和动画都将恢复为默认设置。","s3.chat.confirmResetLookOk":"恢复","s3.chat.confirmClearLearningText":"AI 将不再把你点过赞的回复作为示例。"}""",
        ["zh-TW"] = """{"s3.chat.greeting1":"今天想了解些什麼？","s3.chat.greeting2":"有想整理的想法嗎？我們可以一起梳理清楚。","s3.chat.greeting3":"想解答問題、比較選項，還是規劃一件事？","s3.chat.greeting4":"我們從哪裡開始？說說你想解決什麼。","s3.chat.greeting5":"我可以逐步說明一個主題，也可以整理重點。","s3.chat.greeting6":"正在處理什麼事情嗎？我可以幫你拆成更小的步驟。","s3.chat.greeting7":"可以從一個問題、一份草稿，或一個想繼續探索的想法開始。","s3.chat.greeting8":"現在更需要哪種協助：說明、檢查內容，還是提供新想法？","s3.chat.confirmDeleteConversationTitle":"要刪除此對話嗎？","s3.chat.confirmDeleteConversationText":"此對話將從離線聊天中刪除，且無法復原。","s3.chat.confirmDeleteConversationOk":"刪除","s3.chat.confirmDeleteModelTitle":"要刪除此模型嗎？","s3.chat.confirmDeleteModelText":"此檔案將從這台電腦移除，之後仍可重新下載。","s3.chat.confirmDeleteModelOk":"刪除模型","s3.chat.confirmDeleteAllTitle":"要刪除所有對話嗎？","s3.chat.confirmDeleteAllText":"此操作無法復原。","s3.chat.confirmDeleteAllOk":"全部刪除","s3.chat.confirmClearMessagesTitle":"要清除訊息嗎？","s3.chat.confirmClearMessagesText":"對話仍會留在清單中，但內容會清空。","s3.chat.confirmClearMessagesOk":"清除","s3.chat.confirmClearAiTitle":"要刪除 AI 設定嗎？","s3.chat.confirmClearAiText":"此應用程式中儲存的 API 金鑰與連線資訊將會刪除。","s3.chat.confirmClearAiOk":"刪除","s3.chat.confirmResetLookTitle":"要還原預設外觀嗎？","s3.chat.confirmResetLookText":"主題、背景、暗度、特效和動畫都會還原為預設設定。","s3.chat.confirmResetLookOk":"還原","s3.chat.confirmClearLearningText":"AI 將不再把你按讚的回覆作為範例。"}""",
        ["hi"] = """{"s3.chat.greeting1":"आज आप क्या जानना चाहेंगे?","s3.chat.greeting2":"क्या कोई विचार है जिसे आप व्यवस्थित करना चाहते हैं? हम उसे साथ मिलकर बेहतर बना सकते हैं।","s3.chat.greeting3":"किसी सवाल का जवाब ढूँढ़ें, विकल्पों की तुलना करें या कोई योजना बनाएँ?","s3.chat.greeting4":"कहाँ से शुरू करें? बताइए कि आप क्या सुलझाने की कोशिश कर रहे हैं।","s3.chat.greeting5":"मैं किसी विषय को चरण-दर-चरण समझा सकता हूँ या मुख्य बातें संक्षेप में बता सकता हूँ।","s3.chat.greeting6":"किसी काम पर आगे बढ़ रहे हैं? मैं उसे छोटे चरणों में बाँटने में मदद कर सकता हूँ।","s3.chat.greeting7":"कोई सवाल, मसौदा या ऐसा विचार साझा करें जिसे आप आगे समझना चाहते हैं।","s3.chat.greeting8":"अभी किससे ज़्यादा मदद मिलेगी: कोई व्याख्या, समीक्षा या नए विचार?","s3.chat.confirmDeleteConversationTitle":"क्या यह बातचीत हटानी है?","s3.chat.confirmDeleteConversationText":"यह ऑफ़लाइन चैट से हट जाएगी और वापस नहीं लाई जा सकेगी।","s3.chat.confirmDeleteConversationOk":"हटाएँ","s3.chat.confirmDeleteModelTitle":"क्या यह मॉडल हटाना है?","s3.chat.confirmDeleteModelText":"फ़ाइल इस PC से हट जाएगी। आप इसे बाद में फिर डाउनलोड कर सकते हैं।","s3.chat.confirmDeleteModelOk":"मॉडल हटाएँ","s3.chat.confirmDeleteAllTitle":"क्या सभी बातचीत हटानी हैं?","s3.chat.confirmDeleteAllText":"इस कार्रवाई को वापस नहीं किया जा सकता।","s3.chat.confirmDeleteAllOk":"सब हटाएँ","s3.chat.confirmClearMessagesTitle":"क्या संदेश साफ़ करने हैं?","s3.chat.confirmClearMessagesText":"बातचीत सूची में रहेगी, लेकिन उसमें कोई संदेश नहीं होगा।","s3.chat.confirmClearMessagesOk":"साफ़ करें","s3.chat.confirmClearAiTitle":"क्या AI सेटिंग हटानी हैं?","s3.chat.confirmClearAiText":"इस ऐप में सहेजी गई API कुंजी और कनेक्शन हट जाएँगे।","s3.chat.confirmClearAiOk":"हटाएँ","s3.chat.confirmResetLookTitle":"क्या दिखावट को डिफ़ॉल्ट पर लौटाना है?","s3.chat.confirmResetLookText":"थीम, बैकग्राउंड, डिमिंग, इफ़ेक्ट और ऐनिमेशन डिफ़ॉल्ट पर लौट जाएँगे।","s3.chat.confirmResetLookOk":"रीसेट करें","s3.chat.confirmClearLearningText":"AI अब आपके पसंद किए गए जवाबों को उदाहरण के 